import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  Building2, PhoneCall, ShieldCheck,
  ChevronRight, MapPin, Mail, Clock,
  CheckCircle2, Award, Sparkles, Send
} from 'lucide-react';
import styles from './InfoPage.module.css';

export default function InfoPage({ page }) {
  const location = useLocation();
  const pathSlug = location.pathname.replace(/^\//, '');
  const currentSlug = pathSlug || page || 'about-us';

  // Scroll to top whenever page route changes
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'instant' });
  }, [location.pathname]);

  // State for Contact Us form
  const [contactSubmitted, setContactSubmitted] = useState(false);
  const [formData, setFormData] = useState({ name: '', phone: '', email: '', message: '' });

  const handleContactSubmit = (e) => {
    e.preventDefault();
    if (!formData.name || !formData.phone) return;
    setContactSubmitted(true);
  };

  return (
    <div className={styles.pageWrap}>
      <div className={styles.container}>
        {/* Breadcrumb */}
        <div className={styles.breadcrumb}>
          <Link to="/" className={styles.breadLink}>Home</Link>
          <ChevronRight size={13} />
          <span className={styles.breadCurrent}>
            {getPageTitle(currentSlug)}
          </span>
        </div>

        {/* Main Content Area (Clean Centered Full Width) */}
        <main className={styles.contentCard}>
          {renderPageContent(currentSlug, {
            formData,
            setFormData,
            contactSubmitted,
            handleContactSubmit,
          })}
        </main>
      </div>
    </div>
  );
}

function getPageTitle(slug) {
  switch (slug) {
    case 'about-us':       return 'About Us';
    case 'careers':        return 'Careers';
    case 'contact-us':     return 'Contact Us';
    case 'privacy':        return 'Privacy Policy';
    case 'user-agreement': return 'User Agreement';
    case 'guide':          return 'PropGuide';
    case 'nri-services':   return 'NRI Services';
    case 'how-to-buy':     return 'How to Buy';
    default:               return 'Information';
  }
}

function renderPageContent(slug, contactState) {
  switch (slug) {
    case 'about-us':
      return <AboutUsView />;
    case 'careers':
      return <CareersView />;
    case 'contact-us':
      return <ContactUsView {...contactState} />;
    case 'privacy':
      return <PrivacyPolicyView />;
    case 'user-agreement':
      return <UserAgreementView />;
    case 'guide':
      return <PropGuideView />;
    case 'nri-services':
      return <NriServicesView />;
    case 'how-to-buy':
      return <HowToBuyView />;
    default:
      return <AboutUsView />;
  }
}

/* ── 1. ABOUT US VIEW ───────────────────────────────────────── */
function AboutUsView() {
  return (
    <>
      <div className={styles.heroBanner}>
        <span className={styles.heroTag}>Corporate Overview</span>
        <h1 className={styles.heroTitle}>About ProBridge</h1>
        <p className={styles.heroSub}>
          We connect the world of real estate. ProBridge is India’s premier tech-enabled real estate advisory platform committed to delivering transparent, verified, and hassle-free property experiences.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>Our Vision &amp; Mission</h2>
        <p className={styles.paragraph}>
          Probridge.co.in is built on the foundation of trust and empowerment. Founded with a mission to bring complete transparency to India's dynamic property market, we bridge the gap between discerning homebuyers, verified property owners, and trusted corporate developers.
        </p>
        <p className={styles.paragraph}>
          From discovery to physical site visits, document verification, home loan assistance, and final key handover, ProBridge supports buyers at every step of their journey.
        </p>

        <div className={styles.grid2}>
          <div className={styles.featureCard}>
            <ShieldCheck size={26} color="#0D5F4E" />
            <div className={styles.featureCardTitle}>100% Physical Verification</div>
            <p className={styles.featureCardText}>
              Every home and plot listed on our platform undergoes rigorous on-ground physical inspection and legal paperwork vetting.
            </p>
          </div>

          <div className={styles.featureCard}>
            <Award size={26} color="#0D5F4E" />
            <div className={styles.featureCardTitle}>Zero Brokerage Options</div>
            <p className={styles.featureCardText}>
              Thousands of direct owner listings and premium builder-partner units available without unnecessary middleman charges.
            </p>
          </div>
        </div>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>Why Homebuyers Choose ProBridge</h2>
        <div className={styles.grid2}>
          <div className={styles.featureCard}>
            <Building2 size={24} color="#0D5F4E" />
            <div className={styles.featureCardTitle}>Top Developers &amp; Projects</div>
            <p className={styles.featureCardText}>
              Official channel partnerships with India’s leading builders including Prestige, Godrej, Sobha, Brigade, and DLF.
            </p>
          </div>

          <div className={styles.featureCard}>
            <PhoneCall size={24} color="#0D5F4E" />
            <div className={styles.featureCardTitle}>Dedicated Relationship Managers</div>
            <p className={styles.featureCardText}>
              Personalized advisory, site-visit cab arrangements, negotiation support, and home loan assistance from leading banks.
            </p>
          </div>
        </div>
      </div>
    </>
  );
}

/* ── 2. CAREERS VIEW ────────────────────────────────────────── */
function CareersView() {
  const ROLES = [
    { title: 'Real Estate Portfolio Advisor', dept: 'Advisory & Sales', loc: 'Chennai & Bengaluru', type: 'Full-time' },
    { title: 'Frontend React / React Native Engineer', dept: 'Technology & Product', loc: 'Remote / Hybrid', type: 'Full-time' },
    { title: 'Property Verification Specialist', dept: 'Field Operations', loc: 'Chennai', type: 'Full-time' },
    { title: 'Digital Growth Marketing Manager', dept: 'Marketing', loc: 'Bengaluru', type: 'Full-time' },
  ];

  return (
    <>
      <div className={styles.heroBanner}>
        <span className={styles.heroTag}>Join Our Team</span>
        <h1 className={styles.heroTitle}>Careers at ProBridge</h1>
        <p className={styles.heroSub}>
          Shape the future of Indian proptech. We are looking for passionate innovators, advisors, and engineers to build a better real estate ecosystem.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>Why Work With Us</h2>
        <p className={styles.paragraph}>
          At ProBridge, we champion transparency, meritocracy, and customer-first thinking. Join an energetic team with competitive compensation, health benefits, and tremendous career growth opportunities.
        </p>

        <div className={styles.callout}>
          💡 Interested in working with us? Send your resume and portfolio directly to <a href="mailto:careers@probridge.co.in" style={{ color: '#166534', fontWeight: 700 }}>careers@probridge.co.in</a> or reach out on WhatsApp at <strong>+91 9176663200</strong>.
        </div>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>Open Positions</h2>
        {ROLES.map((role) => (
          <div key={role.title} className={styles.stepRow}>
            <div className={styles.stepContent}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
                <h3 className={styles.stepTitle}>{role.title}</h3>
                <span style={{ fontSize: 12, background: '#E8F5F0', color: '#0D5F4E', padding: '2px 8px', borderRadius: 4, fontWeight: 700 }}>
                  {role.type}
                </span>
              </div>
              <p className={styles.stepDesc}>
                Department: {role.dept} • Location: {role.loc}
              </p>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}

/* ── 3. CONTACT US VIEW ─────────────────────────────────────── */
function ContactUsView({ formData, setFormData, contactSubmitted, handleContactSubmit }) {
  return (
    <>
      <div className={styles.heroBanner}>
        <span className={styles.heroTag}>Get in Touch</span>
        <h1 className={styles.heroTitle}>Contact ProBridge</h1>
        <p className={styles.heroSub}>
          Have queries about a property listing, project booking, or partnership? Reach out to our advisory desk anytime.
        </p>
      </div>

      <div className={styles.contactCardGrid}>
        <div className={styles.contactBox}>
          <MapPin size={22} className={styles.contactBoxIcon} />
          <div>
            <div className={styles.contactBoxLabel}>Corporate Office</div>
            <div className={styles.contactBoxVal}>Batra House, Plot No. 52, Institutional Area, Sector 32, Gurugram, Haryana, 122003</div>
          </div>
        </div>

        <div className={styles.contactBox}>
          <PhoneCall size={22} className={styles.contactBoxIcon} />
          <div>
            <div className={styles.contactBoxLabel}>Phone &amp; WhatsApp</div>
            <div className={styles.contactBoxVal}>+91 9176663200 / 1800-103-104-1</div>
          </div>
        </div>

        <div className={styles.contactBox}>
          <Mail size={22} className={styles.contactBoxIcon} />
          <div>
            <div className={styles.contactBoxLabel}>Support Email</div>
            <div className={styles.contactBoxVal}>customer.service@proptiger.com</div>
          </div>
        </div>

        <div className={styles.contactBox}>
          <Clock size={22} className={styles.contactBoxIcon} />
          <div>
            <div className={styles.contactBoxLabel}>Advisory Desk Hours</div>
            <div className={styles.contactBoxVal}>Monday to Saturday: 9:30 AM to 6:30 PM</div>
          </div>
        </div>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>Send Us a Message</h2>
        {contactSubmitted ? (
          <div className={styles.callout} style={{ background: '#E6F4EA', borderColor: '#16a34a' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 700, fontSize: 15 }}>
              <CheckCircle2 size={18} color="#16a34a" /> Thank You! We Have Received Your Message
            </div>
            <p style={{ margin: '6px 0 0', color: '#166534' }}>
              One of our senior property advisors will get in touch with you at <strong>{formData.phone}</strong> shortly.
            </p>
          </div>
        ) : (
          <form onSubmit={handleContactSubmit} className={styles.contactForm}>
            <div className={styles.formRow2}>
              <div className={styles.inputGroup}>
                <label className={styles.inputLabel}>Your Name *</label>
                <input
                  type="text"
                  required
                  placeholder="e.g. Ramesh Kumar"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className={styles.inputField}
                />
              </div>

              <div className={styles.inputGroup}>
                <label className={styles.inputLabel}>Phone Number *</label>
                <input
                  type="tel"
                  required
                  placeholder="e.g. 9876543210"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  className={styles.inputField}
                />
              </div>
            </div>

            <div className={styles.inputGroup}>
              <label className={styles.inputLabel}>Email Address</label>
              <input
                type="email"
                placeholder="e.g. ramesh@example.com"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                className={styles.inputField}
              />
            </div>

            <div className={styles.inputGroup}>
              <label className={styles.inputLabel}>How Can We Help?</label>
              <textarea
                rows={4}
                placeholder="Tell us what you are looking for (city, locality, budget, property type)..."
                value={formData.message}
                onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                className={styles.inputField}
                style={{ resize: 'vertical' }}
              />
            </div>

            <button type="submit" className={styles.submitBtn}>
              <Send size={15} style={{ verticalAlign: -2, marginRight: 6 }} />
              Submit Message
            </button>
          </form>
        )}
      </div>
    </>
  );
}

/* ── 4. PRIVACY POLICY VIEW ─────────────────────────────────── */
function PrivacyPolicyView() {
  return (
    <>
      <div className={styles.heroBanner}>
        <span className={styles.heroTag}>Legal &amp; Privacy</span>
        <h1 className={styles.heroTitle}>Privacy Policy</h1>
        <p className={styles.heroSub}>
          Learn how ProBridge collects, protects, and handles your personal data across our web and mobile applications in compliance with applicable Indian data protection laws.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>1. Introduction</h2>
        <p className={styles.paragraph}>
          Probridge.co.in ("ProBridge", "we", "us", or "our") is dedicated to safeguarding your privacy. This Privacy Policy outlines our practices regarding data collection, storage, and usage when you visit our website, mobile apps, or engage our property advisory services.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>2. Information We Collect</h2>
        <p className={styles.paragraph}>
          When you register, schedule a site visit, or submit an enquiry, we collect information including your name, contact phone number, email address, property preferences, and location details. We also collect technical diagnostic information such as IP addresses, device identifiers, and browser cookies to provide a personalized browsing experience.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>3. How We Use Your Information</h2>
        <p className={styles.paragraph}>
          We use your data solely to connect you with verified sellers or builder partners, arrange site visits, process enquiry requests, provide customer support, and inform you of new matching property launches. We never sell your personal data to unauthorized third-party advertisers.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>4. Data Security</h2>
        <p className={styles.paragraph}>
          All information transmitted through ProBridge is protected using industry-standard SSL encryption and strict database access controls. For privacy inquiries or data removal requests, contact our compliance officer at <strong>customer.service@proptiger.com</strong>.
        </p>
      </div>
    </>
  );
}

/* ── 5. USER AGREEMENT VIEW ─────────────────────────────────── */
function UserAgreementView() {
  return (
    <>
      <div className={styles.heroBanner}>
        <span className={styles.heroTag}>Terms of Service</span>
        <h1 className={styles.heroTitle}>User Agreement</h1>
        <p className={styles.heroSub}>
          Terms and conditions governing the use of ProBridge platform, search services, listing tools, and advisory features.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>1. Acceptance of Terms</h2>
        <p className={styles.paragraph}>
          By accessing or using ProBridge (probridge.co.in) or our associated mobile applications, you agree to comply with and be bound by this User Agreement. If you do not agree to these terms, please do not use the platform.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>2. Platform Role</h2>
        <p className={styles.paragraph}>
          ProBridge operates as a verified real estate discovery and advisory platform. We connect potential buyers, tenants, owners, and developers. While we verify property documentation and physical existence to the best of our technical capability, all parties are advised to perform independent legal due diligence prior to final transaction execution.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>3. User Conduct &amp; Prohibited Actions</h2>
        <p className={styles.paragraph}>
          Users agree to provide accurate, truthful details when posting properties or requesting callbacks. Submitting fraudulent listings, unauthorized property photos, or spam enquiries will result in immediate permanent account termination.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>4. Governing Law</h2>
        <p className={styles.paragraph}>
          This User Agreement is governed by the laws of India. Any disputes arising out of the use of this service shall be subject to the exclusive jurisdiction of the courts of Gurugram / Chennai, India.
        </p>
      </div>
    </>
  );
}

/* ── 6. PROPGUIDE VIEW ──────────────────────────────────────── */
function PropGuideView() {
  const ARTICLES = [
    {
      title: 'First-Time Homebuyer Complete Checklist (2026 Edition)',
      category: 'Buying Guide',
      readTime: '6 min read',
      desc: 'Step-by-step guidance from down payments and credit scores to builder verification, legal checks, and registration costs.',
    },
    {
      title: 'Understanding RERA: How Real Estate Regulation Protects You',
      category: 'Legal & Compliance',
      readTime: '5 min read',
      desc: 'Why every project must have an active RERA number, how to check project delivery deadlines, and your rights if possession is delayed.',
    },
    {
      title: 'Carpet Area vs Built-Up Area vs Super Built-Up Area Explained',
      category: 'Property Specs',
      readTime: '4 min read',
      desc: 'Never overpay for loading. Learn the mathematical difference between usable carpet area, balcony spaces, and common amenities.',
    },
    {
      title: 'Top Emerging Real Estate Investment Hubs in India',
      category: 'Investment Trends',
      readTime: '7 min read',
      desc: 'Comprehensive analysis of high-growth corridors in Bengaluru, Chennai, Hyderabad, and Pune driven by metro expansions and IT hubs.',
    },
  ];

  return (
    <>
      <div className={styles.heroBanner}>
        <span className={styles.heroTag}>Real Estate Knowledge Hub</span>
        <h1 className={styles.heroTitle}>PropGuide by ProBridge</h1>
        <p className={styles.heroSub}>
          Expert guides, legal insights, taxation tips, and market analysis to help you make confident, informed real estate investment decisions.
        </p>
      </div>

      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>Featured Real Estate Guides</h2>
        {ARTICLES.map((art) => (
          <div key={art.title} className={styles.stepRow}>
            <div className={styles.stepContent}>
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 6 }}>
                <span style={{ fontSize: 11, background: '#E8F5F0', color: '#0D5F4E', padding: '2px 8px', borderRadius: 4, fontWeight: 700 }}>
                  {art.category}
                </span>
                <span style={{ fontSize: 12, color: '#94a3b8' }}>• {art.readTime}</span>
              </div>
              <h3 className={styles.stepTitle}>{art.title}</h3>
              <p className={styles.stepDesc}>{art.desc}</p>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}

/* ── 7. NRI SERVICES VIEW ───────────────────────────────────── */
function NriServicesView() {
